<?php
namespace App\Services;use App\Core\Database;
final class CheckoutService{public function quote(int $planId,string $cycle,?string $couponCode=null):array{$cycles=['monthly'=>'monthly_price','quarterly'=>'quarterly_price','semiannual'=>'semiannual_price','annual'=>'annual_price'];if(!isset($cycles[$cycle]))throw new \DomainException('Periodicidade inválida.');$pdo=Database::connection();$s=$pdo->prepare('SELECT * FROM plans WHERE id=:id AND active=1');$s->execute(['id'=>$planId]);$plan=$s->fetch();if(!$plan)throw new \DomainException('Plano indisponível.');$subtotal=(float)($plan[$cycles[$cycle]]??0);if($subtotal<=0)throw new \DomainException('Preço não configurado.');$discount=0;$coupon=null;if($couponCode){$q=$pdo->prepare('SELECT * FROM coupons WHERE code=:code AND active=1 AND (valid_from IS NULL OR valid_from<=NOW()) AND (valid_until IS NULL OR valid_until>=NOW()) AND (max_uses IS NULL OR uses_count<max_uses) LIMIT 1');$q->execute(['code'=>strtoupper(trim($couponCode))]);$coupon=$q->fetch();if($coupon)$discount=$coupon['type']==='percent'?$subtotal*min(100,(float)$coupon['value'])/100:min($subtotal,(float)$coupon['value']);}return ['plan'=>$plan,'cycle'=>$cycle,'subtotal'=>round($subtotal,2),'discount'=>round($discount,2),'total'=>round($subtotal-$discount,2),'coupon'=>$coupon];}}
